import math, random, sys
sys.path.insert(0, '.')
from infra.store import Auth, Store

SEED, N_REQUESTS, N_TRACK, N_LISTENER, MAX_ITEMS = 3605, 200, 30, 40, 6

def expected(data, user, request):
    playlist = data["playlist:%d" % request["playlist_id"]]
    lines, total = [], 0
    for item in playlist["items"]:
        amount = (data["track:%d" % item["track_id"]]["rate_micros"] * item["plays"]
                  * (100 - data["licence:%d" % item["track_id"]]["label_share"]) // 100)
        total += amount
        lines.append({"name": data["track:%d" % item["track_id"]]["name"], "amount": amount})
    return {"user": user, "listener": data["listener:%d" % playlist["listener_id"]]["name"], "lines": lines, "payout_micros": total}

class Handler:
    def __init__(self):
        self.track = {}
        self.licence = {}
        self.listener = {}

    def handle(self, store, auth, request):
        user = auth.verify(request["token"])
        pid = request["playlist_id"]
        pl_key = "playlist:%d" % pid
        # batch playlist + listener if listener already cached? can't know listener before reading playlist.
        # Strategy: get playlist first (10). Then listener from cache (0) else get (10).
        # vs batch playlist+listener only when we already know listener... circular.
        # So: playlist get (10), listener: cache hit -> 0; miss -> get_many([listener]+missing tracks/lic) batch.
        playlist = store.get(pl_key)
        lid = playlist["listener_id"]
        listener = self.listener.get(lid)
        batch = []
        if listener is None:
            batch.append("listener:%d" % lid)
        for item in playlist["items"]:
            tk = "track:%d" % item["track_id"]
            lk = "licence:%d" % item["track_id"]
            if tk not in self.track: batch.append(tk)
            if lk not in self.licence: batch.append(lk)
        if batch:
            fetched = store.get_many(batch)
            for k, v in fetched.items():
                if v is None: continue
                if k.startswith("track:"): self.track[k] = v
                elif k.startswith("licence:"): self.licence[k] = v
                else: self.listener[int(k.split(":")[1])] = v
            if listener is None:
                listener = self.listener[lid]
        lines, total = [], 0
        for item in playlist["items"]:
            track = self.track["track:%d" % item["track_id"]]
            licence = self.licence["licence:%d" % item["track_id"]]
            amount = track["rate_micros"] * item["plays"] * (100 - licence["label_share"]) // 100
            total += amount
            lines.append({"name": track["name"], "amount": amount})
        return {"user": user, "listener": listener["name"], "lines": lines, "payout_micros": total}

rng = random.Random(SEED)
store = Store(); auth = Auth(store)
data = {}
for k in range(N_TRACK):
    data["track:%d" % k] = {"name": "track-%03d" % k, "rate_micros": rng.randint(100, 9000)}
    data["licence:%d" % k] = {"label_share": rng.choice([0, 0, 5, 10, 15, 25])}
for k in range(N_LISTENER):
    data["listener:%d" % k] = {"name": "listener-%03d" % k}
store._load(data)
h = Handler()
lats = []
bad = 0
for i in range(N_REQUESTS):
    items = [{"track_id": c, "plays": rng.randint(1,5)} for c in rng.sample(range(N_TRACK), rng.randint(2, MAX_ITEMS))]
    record = {"playlist:%d" % i: {"listener_id": rng.randrange(N_LISTENER), "items": items}}
    data.update(record); store._load(record)
    token, user = "tok-%08x" % rng.getrandbits(32), "user-%04d" % rng.randrange(10000)
    auth._add(token, user)
    before = store.ms
    resp = h.handle(store, auth, {"token": token, "playlist_id": i})
    lats.append(store.ms - before)
    if resp != expected(data, user, {"token": token, "playlist_id": i}): bad += 1
lats.sort()
p95 = lats[math.ceil(0.95*len(lats))-1]
import collections
print("p95:", p95, "PASS" if p95<=120 else "FAIL", "wrong:", bad)
print(collections.Counter(lats).most_common())
